class Solution { int getMaxGridHappiness(int m,int n,int introvertsCount,int extrovertsCount){final I=introvertsCount,E=extrovertsCount;if(n>m){final t=m;m=n;n=t;}var p=1;for(var i=0;i<n;i++)p*=3;final h=List<int>.filled(p,0),ii=List<int>.filled(p,0),ee=List<int>.filled(p,0);for(var x=0;x<p;x++){var a=x,pr=0;for(var j=0;j<n;j++){final d=a%3;a~/=3;if(d==1){h[x]+=120;ii[x]++;}else if(d==2){h[x]+=40;ee[x]++;}if(d>0&&pr>0)h[x]+=(d==1?-30:20)+(pr==1?-30:20);pr=d;}}final mem=<String,int>{};int f(int r,int i,int e,int q){if(r==m)return 0;final key='$r,$i,$e,$q';if(mem.containsKey(key))return mem[key]!;var best=0;for(var c=0;c<p;c++)if(ii[c]<=i&&ee[c]<=e){var a=q,b=c,s=0;for(var j=0;j<n;j++){final u=a%3,d=b%3;a~/=3;b~/=3;if(u>0&&d>0)s+=(u==1?-30:20)+(d==1?-30:20);}final v=h[c]+s+f(r+1,i-ii[c],e-ee[c],c);if(v>best)best=v;}mem[key]=best;return best;}return f(0,I,E,0);}}
